        thumbColor={value ? theme.palette.primary : theme.palette.text.secondary}
      />
    </View>
  );

  return (
    <ScrollView style={styles.container}>
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Darstellung</Text>
