import React, { useMemo, useState } from 'react';
import { Alert, FlatList, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';

type Item = { id: string; title: string; note?: string };

export default function CrudScreen() {
  const [title, setTitle] = useState('');
  const [note, setNote] = useState('');
  const [items, setItems] = useState<Item[]>([]);

  const canAdd = useMemo(() => title.trim().length > 0, [title]);

  const addItem = () => {
    const t = title.trim();
    if (!t) return;

    const id = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
    setItems((prev) => [{ id, title: t, note: note.trim() || undefined }, ...prev]);
    setTitle('');
    setNote('');
  };

  const removeItem = (id: string) => {
    setItems((prev) => prev.filter((x) => x.id !== id));
  };

  const clearAll = () => {
    if (items.length === 0) return;
    Alert.alert('Alles löschen?', 'Willst du wirklich alle Einträge entfernen?', [
      { text: 'Abbrechen', style: 'cancel' },
      { text: 'Löschen', style: 'destructive', onPress: () => setItems([]) },
    ]);
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>CRUD Demo</Text>
      <Text style={styles.subtitle}>
        Lokale Liste (Create / Read / Delete). Kein Backend — ideal als Template-Startpunkt.
      </Text>

      <View style={styles.form}>
        <TextInput
          placeholder="Titel"
          value={title}
          onChangeText={setTitle}
          style={styles.input}
          autoCapitalize="sentences"
          autoCorrect
        />
        <TextInput
          placeholder="Notiz (optional)"
          value={note}
          onChangeText={setNote}
          style={styles.input}
          autoCapitalize="sentences"
          autoCorrect
        />
        <View style={styles.row}>
          <Pressable
            onPress={addItem}
            disabled={!canAdd}
            style={({ pressed }) => [
              styles.button,
              !canAdd && styles.buttonDisabled,
              pressed && canAdd && styles.buttonPressed,
            ]}
          >
            <Text style={styles.buttonText}>Hinzufügen</Text>
          </Pressable>

          <Pressable
            onPress={clearAll}
            disabled={items.length === 0}
            style={({ pressed }) => [
              styles.ghostButton,
              items.length === 0 && styles.ghostButtonDisabled,
              pressed && items.length > 0 && styles.ghostButtonPressed,
            ]}
          >
            <Text style={styles.ghostButtonText}>Alles löschen</Text>
          </Pressable>
        </View>
      </View>

      <FlatList
        data={items}
        keyExtractor={(it) => it.id}
        contentContainerStyle={styles.list}
        ListEmptyComponent={<Text style={styles.empty}>Noch keine Einträge.</Text>}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <View style={styles.cardHeader}>
              <Text style={styles.cardTitle}>{item.title}</Text>
              <Pressable onPress={() => removeItem(item.id)} style={styles.deleteBtn}>
                <Text style={styles.deleteText}>✕</Text>
              </Pressable>
            </View>
            {!!item.note && <Text style={styles.cardNote}>{item.note}</Text>}
          </View>
        )}
      />
    </View>
  );
}

